      for (var i = 1; i < own.length; i++) if (own[i].m > origin.m) origin = own[i];
      var dx = state.lock.x - origin.x, dy = state.lock.y - origin.y;
      var len = Math.sqrt(dx * dx + dy * dy);
      if (!len || !isFinite(len)) return false;
