      var curLen = Math.sqrt(curX * curX + curY * curY);
      if (!curLen) { dv.setInt32(1, Math.round(nx * 100), true); dv.setInt32(5, Math.round(ny * 100), true); return true; }
      var cxn = curX / curLen, cyn = curY / curLen;
      var mixX = cxn * (1 - w) + nx * w, mixY = cyn * (1 - w) + ny * w;
