      if (!(bpx > 0)) return '';
      var bx = Math.round(bpx * 10) / 10 + 'px';
      var bg = which === 'chat' ? '--hud-chat-bg' : which === 'mm' ? '--hud-minimap-bg' : '--hud-leaderboard-bg';
