    if (!cell || typeof cell.x !== 'number' || typeof cell.y !== 'number' || !isFinite(cell.x) || !isFinite(cell.y)) {
      s.why = (sc && sc.selfWhy) || 'your own cell is not in the scene';
      return null;
    }
    s.v = { x: cell.x, y: cell.y }; s.at = Date.now();
