    MXPOS.at = now;
    var order = ['native', 'scene', 'camera'], got = {}, i;
    for (i = 0; i < order.length; i++) {
      var k = order[i], v = null, st = MXPOS[k];
      try { v = k === 'native' ? mxPosNative() : k === 'scene' ? mxPosScene() : mxPosCamera(); } catch (e) { v = null; }
      got[k] = v;
      if (!v) continue;
      var prev = MXPOS.freeze[k];
      if (!prev || prev.x !== v.x || prev.y !== v.y) {
        st.changedAt = now;
        MXPOS.freeze[k] = { x: v.x, y: v.y };
        delete MXPOS.demote[k];            // it moved: it is a live source again
      } else if (!st.changedAt) st.changedAt = now;
    }
    var win = '', winIdx = -1;
    for (i = 0; i < order.length; i++) {
      if (!got[order[i]]) continue;
      if (MXPOS.demote[order[i]] && now < MXPOS.demote[order[i]]) continue;
      win = order[i]; winIdx = i; break;
    }
    if (win) {
      var wst = MXPOS[win];
      if (now - (wst.changedAt || now) > 4000) {
        for (var j = winIdx + 1; j < order.length; j++) {
          var lk = order[j], lst = MXPOS[lk];
          if (!got[lk] || now - (lst.changedAt || now) > 4000) continue;
          MXPOS.demote[win] = now + 6000;   // frozen while a lower source moves: stand down
          MXPOS.last = { x: got[lk].x, y: got[lk].y, src: lk, at: now, frozen: win };
          MXPOS.winner = lk;
          return MXPOS.last;
        }
      }
    }
    if (!win) { MXPOS.last = null; MXPOS.winner = ''; return null; }
    MXPOS.last = { x: got[win].x, y: got[win].y, src: win, at: now };
