      if (Date.now() < session.escLeaveUntil || Date.now() < session.suppressUntil) { mxDesync.strikes = 0; return; }
      var shown;
      try { shown = nativeMenuShown(); } catch (eNS) { return; }
      if (!shown) { session.live = true; mxDesync.strikes = 0; return; }   // in a match: nothing stranded
