      // alone for mxSleepEsc (wake); Tab/Enter/Space inside the sleep card keep
      // working for keyboard wake. Everything else is swallowed in capture so the
      // game never sees movement/split/macro keys while asleep.
      try {
        if (typeof mxPaused !== 'undefined' && mxPaused) {
          if (e.key === 'Escape') return;
          var ae = DOC.activeElement;
          var inCard = ae && ae.closest && ae.closest('.mx-sleep-card');
          if ((e.key === 'Tab' || e.key === 'Enter' || e.key === ' ') && inCard) return;
          try { e.preventDefault(); e.stopImmediatePropagation(); e.stopPropagation(); } catch (eSw2) {}
          return;
        }
      } catch (eG) {}

      // 1.30.0: Esc is the “leave the game” key while you are playing. The game’s own Spectate path is used so the cell is
      // really removed and the menu opens on top; dead/spectating or in the lobby,
      // Esc keeps its plain menu behaviour. Every Escape tells the death watcher
      // this is a menu, so it can never be mistaken for a death.
      // v1.56.1: Esc is ALWAYS swallowed here, in capture, before the game sees it.
      // It used to be only preventDefaulted, so the game's own Escape listener still
